void HAL_CAN_RxFifo0MsgPendingCallback(CAN_HandleTypeDef* h)
{
    if (h != &hcan1) return;
    CAN_RxHeaderTypeDef hdr;
    uint8_t data[8];
    if (HAL_CAN_GetRxMessage(&hcan1, CAN_RX_FIFO0, &hdr, data) != HAL_OK) return;
    if (hdr.IDE != CAN_ID_STD || hdr.RTR != CAN_RTR_DATA) return;

    uint32_t cobid = hdr.StdId & 0x7FFu;
    uint8_t len = hdr.DLC;

    // Generic hook first
    odapp_on_can_rx(cobid, data, len);

    const uint8_t node = APP_CANOPEN_NODE_ID;

#if APP_PARSE_TPDO1_SVE
    if (cobid == (0x180u + node)) {
        uint16_t sw=0, ec=0; int32_t va=0;
        if (odapp_parse_tpdo1_sve(node, cobid, data, len, &sw, &va, &ec) == 0) {
            app_on_tpdo1_sve(node, sw, va, ec);
        }
    }
#endif

#if APP_PARSE_HEARTBEAT
    if (cobid == (0x700u + node)) {
        odapp_nmt_state_t st;
        if (odapp_parse_heartbeat(node, cobid, data, len, &st) == 0) {
            app_on_heartbeat(node, (uint8_t)st);
        }
    }
#endif

#if APP_PARSE_SDO_RESP
#if 0
    if (cobid == (0x580u + node)) {
        ODAPP_SDOParsed p;
        if (len >= 8 && odapp_sdo_parse_response(data,len,  &p) == 0) {
            uint32_t aux = 0;
            if (p.kind == ODAPP_SDO_KIND_ABORT) aux = p.abort_code;
            else if (p.kind == ODAPP_SDO_KIND_UL_INIT_RESP) {
                // pack first up to 4 bytes for convenience
                aux = (uint32_t)p.data[0] | ((uint32_t)p.data[1]<<8) |
                      ((uint32_t)p.data[2]<<16) | ((uint32_t)p.data[3]<<24);
            }
            app_on_sdo_response(node, (uint8_t)p.kind, p.index, p.sub, aux);
        }
        // Also feed minimal SDO client matcher (for blocking writes)
        _sdo_match_response(cobid, data, len);
    }
#endif
#endif
}
